{
  "spells": [
    {
      "id": "spell_life_07",
      "theory": "施术者将魔力化作极细的根须状丝线，从掌心渗入土壤，沿着湿气与矿物质的浓度梯度探向现有水源。这些丝线只传递生长信号，不凭空造水，也不改变土质。幼根受信号引导后仍需数日自行生长，期间依赖原有水分与养料，若水源过远或土层干硬，根须便无法抵达。",
      "casting": "单膝跪地，掌心贴土，以拇指为轴画半圆，同时将魔力缓缓压入土中，保持呼吸平稳直到指尖感到微凉。",
      "failure": "魔力散成紊乱的细丝，幼根朝错误方向卷曲或停止生长。施术者掌心发麻，土壤表面可能留下焦痕，数日内该处草籽不再萌发。",
      "counters": [
        "在引导路径上埋入干燥的灰烬层，可扰乱魔力丝线的浓度感知。",
        "用石片压住施术点周围的表土，阻断根须延伸的物理通道。"
      ],
      "socialConsequences": "河谷农户常请人引导菜园或果园的幼根靠近沟渠，乡约见证下只需口头约定，不另立字据。若有人把根须引向邻家水井方向，即使未造成实际取水，也会被视作侵占水源的苗头，乡老会要求当面解释并移回原处。城中园丁则更谨慎，公会记录显示根系越界纠纷多因未事先丈量地界。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时根须方向易偏，需反复确认水源大致方位。",
        "熟练后能感知土层湿度差异，减少无效引导。",
        "专精者可控制根须分叉数量，避免过度消耗幼根活力。",
        "大师级仍受水源距离限制，但能精确避开石块与硬层。"
      ]
    },
    {
      "id": "spell_life_08",
      "theory": "魔力以极细的感知触须附着在目标体表，捕捉发热、肿胀、变色等常见感染征象，并将这些信号传回施术者指尖。它只能指出征象，不能分离病原或判断病因，因此无法替代实际观察与经验。触须不穿透皮肤，也不进入血液，对目标无治疗作用。",
      "casting": "手掌悬于目标上方，五指微张，以食指与中指交替轻点空气，形成缓慢的节律，同时将注意力集中在指尖的温感变化上。",
      "failure": "触须信号混乱，施术者感到指尖忽冷忽热，却无法对应具体征象。目标可能因魔力残留而皮肤发痒，数小时内出现无意义的红点，引起不必要的恐慌。",
      "counters": [
        "用湿布覆盖目标体表，可吸收部分感知触须并减弱信号。",
        "在目标周围点燃气味浓烈的草药，可干扰魔力对体表征象的捕捉。"
      ],
      "socialConsequences": "河谷乡间，疫痕辨识常由略通医术的长者施行，乡约允许为发热者检查，但须先征得本人或家属同意。若未经同意对陌生人施术，会被视作窥探隐私，乡老可要求赔偿。城中公会要求施术者登记检查记录，港口则更严，对船员检查后若隐瞒结果导致疫情扩散，港务可追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时只能感知明显发热，容易漏掉轻微征象。",
        "熟练后能区分局部红肿与全身发热的差异。",
        "专精者可同时追踪多处征象，但无法确定病因。",
        "大师级仍不能替代诊断，但能更早发现细微变化。"
      ]
    },
    {
      "id": "spell_life_09",
      "theory": "施术者将魔力化作细密的稳定丝线，缠绕在濒死者的主要生命征象周围，暂缓其恶化速度。丝线不修复伤口，也不补充血液，只维持呼吸与心跳的节律，为后续真实救治争取时间。若没有实际治疗，稳定效果结束后伤者仍会回到原有危重状态。",
      "casting": "将草药置于伤者胸口，双手交叠悬于上方，以缓慢的圆周动作送入魔力，同时低声数息，保持节奏直到感到丝线均匀分布。",
      "failure": "丝线分布不均，伤者呼吸可能短暂平稳后突然紊乱，草药迅速枯萎。施术者会感到双手沉重，数小时内无法再次施术，伤者则可能因节律突变而加重损伤。",
      "counters": [
        "用冷水泼洒伤者面部，可打断魔力丝线的节律同步。",
        "在伤者周围撒布铁屑，可扰乱稳定丝线的附着。"
      ],
      "socialConsequences": "河谷乡约要求施术者先取得伤者家属同意，若家属不在场，可由乡老见证先行施术，但事后须说明。城中公会规定续息术只能在持有救治许可的场所使用，无证施术致人延误治疗可被追责。港口对船员施术尤为谨慎，港务要求记录伤情与施术时间，若因施术掩盖真实伤情导致货损或船员死亡，船主可提起索赔。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时丝线易松脱，稳定时间常短于预期。",
        "熟练后能均匀分布丝线，减少呼吸节律波动。",
        "专精者可延长稳定窗口，但仍需真实救治。",
        "大师级能精确控制丝线收束，避免魔力浪费。"
      ]
    }
  ]
}
